insert into public.micronutrients (key, name, "function") values ('vitamina_c', 'Vitamina C', 'Contribuisce alla normale funzione del sistema immunitario, alla sintesi del collagene e alla protezione delle cellule dallo stress ossidativo.')
insert into public.micronutrients (key, name, "function") values ('vitamina_a', 'Vitamina A / Beta-carotene', 'Il beta-carotene è precursore della vitamina A, importante per la normale funzione visiva, per la pelle e per il sistema immunitario.')
insert into public.micronutrients (key, name, "function") values ('vitamina_k', 'Vitamina K', 'Contribuisce alla normale coagulazione del sangue e al mantenimento di ossa normali.')
insert into public.micronutrients (key, name, "function") values ('folati', 'Folati (Vitamina B9)', 'Contribuiscono alla normale sintesi degli amminoacidi e alla normale formazione del sangue; utili nei periodi di crescita dei tessuti.')
insert into public.micronutrients (key, name, "function") values ('vitamina_b6', 'Vitamina B6', 'Contribuisce al normale metabolismo energetico e alla normale funzione del sistema nervoso.')
insert into public.micronutrients (key, name, "function") values ('potassio', 'Potassio', 'Contribuisce alla normale funzione muscolare, alla funzione del sistema nervoso e al mantenimento di una pressione sanguigna normale.')
insert into public.micronutrients (key, name, "function") values ('magnesio', 'Magnesio', 'Contribuisce al normale metabolismo energetico, alla funzione muscolare e alla riduzione di stanchezza e affaticamento.')
insert into public.micronutrients (key, name, "function") values ('manganese', 'Manganese', 'Contribuisce alla normale formazione del tessuto connettivo e alla protezione delle cellule dallo stress ossidativo.')
insert into public.micronutrients (key, name, "function") values ('polifenoli', 'Polifenoli', 'Ampia famiglia di composti vegetali con documentata attività antiossidante in vitro; contribuiscono al colore e al sapore di frutta e verdura.')
insert into public.micronutrients (key, name, "function") values ('antociani', 'Antociani', 'Pigmenti vegetali della famiglia dei polifenoli, responsabili delle tonalità rosse, viola e blu, con attività antiossidante.')
insert into public.micronutrients (key, name, "function") values ('flavonoidi', 'Flavonoidi', 'Sottogruppo dei polifenoli diffuso in agrumi e frutti; contribuiscono alle proprietà antiossidanti dell''alimento.')
insert into public.micronutrients (key, name, "function") values ('licopene', 'Licopene', 'Carotenoide di colore rosso presente soprattutto nel pomodoro e nell''anguria, con attività antiossidante.')
insert into public.micronutrients (key, name, "function") values ('betalaine', 'Betalaine', 'Pigmenti rosso-porpora tipici della barbabietola, con attività antiossidante studiata in vitro.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('mela', 'Mela', 'frutta', '#8FBF5A', '🍎', 0.65, 'Apporta zuccheri naturalmente presenti, potassio e diversi composti polifenolici. Base dolce e versatile.', 'Lavare bene, rimuovere il torsolo. Non serve sbucciare se la buccia è integra.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('pera', 'Pera', 'frutta', '#C7D48A', '🍐', 0.6, 'Dolcezza morbida, fibra solubile e potassio. Rende il succo vellutato.', 'Usare pere mature ma sode. Rimuovere il torsolo; buccia lavata ammessa.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('pesca', 'Pesca', 'frutta', '#F4B183', '🍑', 0.55, 'Zuccheri, beta-carotene e vitamina C. Aroma estivo e delicato.', 'Rimuovere il nocciolo. Preferire pesche mature per una resa migliore.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('nettarina', 'Nettarina', 'frutta', '#F0A57C', '🍑', 0.55, 'Simile alla pesca: zuccheri, carotenoidi e vitamina C, con buccia liscia.', 'Rimuovere il nocciolo. La buccia liscia può essere lasciata dopo lavaggio.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('prugna', 'Prugna', 'frutta', '#8E5B8E', '🫐', 0.5, 'Zuccheri, sorbitolo e polifenoli. Colore intenso e sapore pieno.', 'Rimuovere il nocciolo. Alternare con ingredienti più sodi per estrarre bene.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('uva', 'Uva', 'frutta', '#7E57C2', '🍇', 0.7, 'Zuccheri prontamente disponibili, potassio e polifenoli (soprattutto uva nera).', 'Staccare gli acini dal grappolo. Ottima resa; molto dolce, dosare con equilibrio.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('arancia', 'Arancia', 'frutta', '#F59E42', '🍊', 0.5, 'Fonte di vitamina C, folati e flavonoidi. Freschezza agrumata.', 'Sbucciare rimuovendo la parte bianca amara. Non centrifugare la scorza.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('mandarino', 'Mandarino', 'frutta', '#F2933C', '🍊', 0.45, 'Vitamina C e flavonoidi, con dolcezza più marcata dell''arancia.', 'Sbucciare ed eliminare eventuali semi. Non usare la scorza.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('pompelmo', 'Pompelmo', 'frutta', '#EF7E82', '🍊', 0.5, 'Vitamina C, flavonoidi e note amare-acidule che bilanciano i succhi dolci.', 'Sbucciare rimuovendo albedo e membrane. Attenzione a possibili interazioni con farmaci.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('limone', 'Limone', 'frutta', '#F4D35E', '🍋', 0.45, 'Fonte di vitamina C e acido citrico. Ravviva e bilancia la dolcezza.', 'Sbucciare la scorza esterna. Bastano piccole quantità per l''aroma.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('lime', 'Lime', 'frutta', '#B5D33D', '🍋', 0.4, 'Acido citrico e vitamina C, con aroma più intenso e verde del limone.', 'Sbucciare la scorza. Usare in piccole dosi per non coprire gli altri sapori.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('ananas', 'Ananas', 'frutta', '#F2C94C', '🍍', 0.55, 'Zuccheri, vitamina C e manganese. Sapore tropicale e leggermente acidulo.', 'Eliminare buccia e parte centrale più fibrosa. Molto succoso.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('anguria', 'Anguria', 'frutta', '#F76C6C', '🍉', 0.72, 'Molto idratante, apporta licopene e potassio con poche calorie.', 'Rimuovere la buccia. Resa altissima; il succo è molto liquido e dolce.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('melone', 'Melone', 'frutta', '#F6B26B', '🍈', 0.6, 'Beta-carotene, vitamina C e potassio. Dolcezza aromatica e idratante.', 'Rimuovere buccia e semi. Preferire melone maturo e profumato.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('kiwi', 'Kiwi', 'frutta', '#7CB342', '🥝', 0.55, 'Elevato contenuto di vitamina C, con potassio e polifenoli.', 'Sbucciare. Non eccedere: i piccoli semi possono dare una nota leggermente amara.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('melograno', 'Melograno', 'frutta', '#C0392B', '🔴', 0.45, 'Ricco di polifenoli e antociani, con vitamina C e sapore agrodolce.', 'Usare solo i chicchi (arilli). Colora intensamente; macchia i tessuti.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('mirtilli', 'Mirtilli', 'frutti-di-bosco', '#5C6BC0', '🫐', 0.55, 'Ricchi di antociani e polifenoli, con poche calorie. Colore blu-viola intenso.', 'Sciacquare delicatamente. Alternare con frutta soda per estrarre meglio.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('more', 'More', 'frutti-di-bosco', '#6A1B9A', '🫐', 0.5, 'Antociani, vitamina C e manganese. Sapore intenso e leggermente acidulo.', 'Sciacquare con cura. Colorano molto; abbinare a mela o pera per equilibrio.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('lamponi', 'Lamponi', 'frutti-di-bosco', '#D81B60', '🍓', 0.45, 'Vitamina C, manganese e polifenoli, con dolcezza tenue e nota acidula.', 'Molto delicati: sciacquare appena. Resa contenuta, aggiungono aroma e colore.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('fragole', 'Fragole', 'frutti-di-bosco', '#EF5350', '🍓', 0.55, 'Buona fonte di vitamina C e polifenoli, con dolcezza fresca e poche calorie.', 'Lavare e rimuovere il picciolo. Scegliere fragole ben mature e profumate.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('ribes', 'Ribes', 'frutti-di-bosco', '#B71C1C', '🔴', 0.5, 'Elevata acidità, vitamina C e antociani. Sapore vivace e pungente.', 'Staccare gli acini dai raspi. Usare in piccole dosi per la spiccata acidità.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('carota', 'Carota', 'verdura', '#F39C12', '🥕', 0.5, 'Ricca di beta-carotene, precursore della vitamina A. Dolcezza naturale e colore arancio.', 'Lavare e spuntare le estremità. Non serve sbucciare se ben lavata; ortaggio duro, alternare con morbidi.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('cetriolo', 'Cetriolo', 'verdura', '#66BB6A', '🥒', 0.75, 'Molto idratante e poco calorico, con potassio. Base neutra e rinfrescante.', 'Lavare bene. Buccia ammessa se non cerata; altrimenti sbucciare. Resa molto alta.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('finocchio', 'Finocchio', 'verdura', '#AED581', '🌿', 0.55, 'Note anice-fresche, potassio e poche calorie. Rende il succo aromatico e leggero.', 'Lavare, eliminare la base dura e le parti esterne rovinate. Tagliare a spicchi.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('sedano', 'Sedano', 'verdura', '#9CCC65', '🥬', 0.6, 'Idratante, con potassio e sodio naturale. Sapore erbaceo e salino.', 'Lavare le coste e rimuovere i filamenti più grossi. Ottima resa liquida.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('barbabietola', 'Barbabietola', 'verdura', '#AD1457', '🔴', 0.55, 'Ricca di betalaine e folati, con sapore terroso e dolce. Colore rubino intenso.', 'Lavare e sbucciare. Cruda ha sapore forte: usare in quantità moderate. Macchia molto.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('pomodoro', 'Pomodoro', 'verdura', '#E53935', '🍅', 0.65, 'Fonte di licopene, vitamina C e potassio, con poche calorie. Sapore savory.', 'Lavare e rimuovere il picciolo. Preferire pomodori maturi e sodi.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('spinaci', 'Spinaci', 'verdura', '#388E3C', '🥬', 0.3, 'Apportano folati, vitamina K, magnesio e clorofilla. Sapore delicato.', 'Lavare accuratamente. Foglia tenera: alternare con frutta soda per estrarre il succo.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('cavolo-riccio', 'Cavolo riccio (kale)', 'verdura', '#2E7D32', '🥬', 0.3, 'Ricco di vitamina K, vitamina C, folati e carotenoidi. Sapore vegetale deciso.', 'Lavare e rimuovere la costa centrale più dura. Alternare con mela o cetriolo.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('lattuga', 'Lattuga', 'verdura', '#9CCC65', '🥬', 0.35, 'Molto leggera e idratante, con folati e vitamina K. Sapore neutro-dolce.', 'Lavare le foglie. Resa modesta: usare come componente idratante e delicata.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('zucca', 'Zucca', 'verdura', '#E8871E', '🎃', 0.45, 'Ricca di beta-carotene (provitamina A) e potassio, con sapore dolce e delicato e poche calorie.', 'Sbucciare ed eliminare semi e filamenti. Ortaggio duro: tagliarlo a pezzi piccoli e alternarlo a ingredienti morbidi. Preferire zucca ben matura.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('zenzero', 'Zenzero', 'aromatici', '#E6B84D', '🫚', 0.4, 'Contiene gingeroli e composti aromatici responsabili della tipica piccantezza.', 'Lavare e, se la buccia è spessa, raschiarla. Basta un piccolo pezzo per aromatizzare.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('curcuma', 'Curcuma fresca', 'aromatici', '#E38B29', '🫚', 0.4, 'Radice aromatica ricca di curcuminoidi, dal colore giallo-arancio intenso.', 'Maneggiare con attenzione: colora molto pelle e superfici. Usare in piccole quantità.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('menta', 'Menta', 'aromatici', '#4DB6AC', '🌿', 0.2, 'Foglia aromatica che aggiunge freschezza e note balsamiche, con oli essenziali.', 'Sciacquare. Aggiungere poche foglie per profumare senza coprire gli altri sapori.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('basilico', 'Basilico', 'aromatici', '#66BB6A', '🌿', 0.2, 'Erba aromatica dalle note dolci-speziate, con oli essenziali caratteristici.', 'Sciacquare. Poche foglie sono sufficienti; si abbina bene a pomodoro e frutta estiva.')
insert into public.ingredients (slug, name, category, color, icon, yield_ratio, contribution, notes) values ('prezzemolo', 'Prezzemolo', 'aromatici', '#43A047', '🌿', 0.25, 'Erba verde ricca di vitamina C, vitamina K e clorofilla, dal sapore intenso.', 'Lavare bene. Usare in piccole quantità: il sapore è deciso e può dominare.')
